function descendant(candidate,ancestor){if(!ancestor)return false;let c=db.content.find(c=>c.id===candidate),seen=new Set;while(c?.parentId&&!seen.has(c.id)){if(c.parentId===ancestor)return true;seen.add(c.id);c=db.content.find(x=>x.id===c.parentId)}return false}
function historyBlock(c){return `<div class="helper full"><h3>Lịch sử chỉnh sửa</h3>${(c.history||[]).slice().reverse().map((h,i)=>`<details><summary>${dateText(h.at)} / ${esc(h.title)} / ${statuses[h.status]||''}</summary><pre class="history-body">${esc(h.body)}</pre><button type="button" data-restore-history="${c.id}" data-hi="${(c.history||[]).length-1-i}">Đưa bản này vào trình soạn</button></details>`).join('')||'<p>Chưa có phiên bản trước. Xưởng giữ tối đa 30 lần thay đổi tiêu đề, nội dung hoặc trạng thái.</p>'}</div>`}
const priorContentPage=contentPage;contentPage=function(){let html=priorContentPage();const cs=filtered();if(cs.length)html+=`<section class="panel mt"><div class="panel-head"><h2>Luồng nội dung liên kết</h2><span class="muted">Dùng lại nội dung, giữ nguồn gốc</span></div>${cs.map(c=>`<div class="row"><div><strong>${esc(c.title)}</strong><small>${esc(c.kind||'Bài viết')}${c.parentId?' / Từ: '+esc(db.content.find(p=>p.id===c.parentId)?.title||'Nội dung gốc'):''}</small><small>${db.assets.filter(a=>a.contentId===c.id).length} ảnh / ${db.workflows.filter(w=>w.contentId===c.id).length} gói nền tảng / ${db.content.filter(w=>w.parentId===c.id).length} phiên bản</small></div><div class="actions"><button data-lineage="${c.id}" data-step="image">Ảnh</button><button data-lineage="${c.id}" data-step="variant">Phiên bản</button><button data-lineage="${c.id}" data-step="pinterest">Pinterest</button><button data-lineage="${c.id}" data-step="etsy">Etsy</button></div></div>`).join('')}</section>`;return html};
const priorPublishPage=publishPage;publishPage=function(){return heading('Xuất bản','Hàng đợi và lịch đăng trong cùng một nơi.')+`<div class="subtabs"><button data-pubtab="queue" class="${publicationMode==='queue'?'selected':''}">Hàng đợi</button><button data-pubtab="calendar" class="${publicationMode==='calendar'?'selected':''}">Lịch tuần / tháng</button></div>`+(publicationMode==='calendar'?calendarPage().slice(calendarPage().indexOf('<div class="filters">')):priorPublishPage().slice(priorPublishPage().indexOf('<div class="notice">')))+`<section class="panel mt"><h2>Lịch và hàng đợi nền tảng</h2>${db.workflows.map(w=>`<div class="row"><div><strong>${esc(w.title)}</strong><small>${w.type==='etsy'?'Etsy':'Pinterest'} / ${w.status==='live'?'Đã đăng':w.status==='approved'?'Đã duyệt':'Nháp'} / ${dateText(w.scheduledAt)}</small></div><div class="actions">${w.contentId?`<button data-edit="content" data-id="${esc(w.contentId)}">Nội dung gốc</button>`:''}<button data-workflow="${w.type}" data-wid="${w.id}">Mở gói đăng</button></div></div>`).join('')||'<p class="muted mt">Chưa có ghim hoặc sản phẩm chuẩn bị đăng.</p>'}</section>`};
