const priorImagesPage=imagesPage;imagesPage=function(){const selected=db.assets.filter(a=>imageMode==='all'||(imageMode==='library'?!!a.data:a.approval==='approved'));return heading('Hình ảnh','Yêu cầu ảnh, ảnh kết quả và duyệt ảnh trong cùng một nơi.','<button class="primary" id="newAsset">+ Chuẩn bị ảnh</button>')+`<div class="subtabs">${[['all','Yêu cầu và kết quả'],['library','Thư viện ảnh'],['approved','Ảnh đã duyệt']].map(([k,l])=>`<button data-imagetab="${k}" class="${imageMode===k?'selected':''}">${l}</button>`).join('')}</div>`+flowNotice('Tạo ảnh bằng AI hiện thực hiện thủ công. Ảnh đã duyệt có thể chọn cho bài viết, Pinterest và Etsy. File gốc được giữ riêng trên thiết bị khi nhập ảnh từ phiên bản này.')+`<div class="cards">${selected.map(a=>`<article class="panel">${a.data?`<img class="asset-preview" src="${esc(a.data)}" alt="${esc(a.alt||a.title)}">`:'<div class="asset-empty">Chưa có ảnh kết quả</div>'}<h2>${esc(a.title)}</h2><small>${esc(a.ratio)} / ${a.approval==='approved'?'Đã duyệt':'Chưa duyệt'}</small><small>${esc(db.content.find(c=>c.id===a.contentId)?.title||'Ảnh độc lập')}</small><div class="actions"><button data-asset="${a.id}">Mở và duyệt</button>${a.data?`<button data-original="${a.id}">Tải ảnh gốc</button>`:''}</div></article>`).join('')}</div>${selected.length?'':`<section class="panel">${empty('Chưa có ảnh trong nhóm này','Chuẩn bị prompt và nhập ảnh kết quả để tiếp tục.','<button id="newAssetEmpty">Chuẩn bị ảnh</button>')}</section>`}`};
const oldWorkflowOpen=openWorkflow;openWorkflow=function(type,id='',defaults={}){oldWorkflowOpen(type,id,defaults);const o={...(type==='asset'?db.assets:db.workflows).find(w=>w.id===id),...defaults};let extra='';if(type==='asset')extra=input('globalStyle','Phong cách ảnh chung',o.globalStyle||ch(db.content.find(c=>c.id===o.contentId)?.channelId)?.visual||'','textarea')+input('scenePrompt','Nội dung riêng của ảnh',o.scenePrompt||db.content.find(c=>c.id===o.contentId)?.title||'','textarea')+input('alt','Mô tả ảnh thay thế',o.alt)+select('approval','Duyệt ảnh',[['draft','Chưa duyệt'],['approved','Đã duyệt']],o.approval||'draft')+`<input type="hidden" name="originalKey" value="${esc(o.originalKey||'')}"><div class="helper">Prompt gửi AI = phong cách chung + nội dung ảnh + tỷ lệ. <button type="button" id="composeLayers">Ghép hai lớp prompt</button></div>`;else extra=input('operationNote','Ghi chú / lỗi cần xử lý',o.operationNote,'textarea')+`<div class="helper">${o.contentId?'Liên kết nội dung gốc: '+esc(db.content.find(c=>c.id===o.contentId)?.title||'Nội dung đã xóa'):'Bạn có thể chọn nội dung liên quan để dùng lại mô tả và ảnh.'}</div>`;$('#workflowFields').insertAdjacentHTML('beforeend',extra);$('#workflowForm button[type="submit"]').disabled=false};
