$('#workflowForm').addEventListener('submit',e=>{const d=wfValues(),fail=text=>{e.preventDefault();e.stopImmediatePropagation();workflowError(text)};if(wfType==='asset'&&d.approval==='approved'&&!assetDraft)return fail('Cần nhập ảnh kết quả trước khi duyệt.');if(wfType!=='asset'&&d.status!=='draft'){const a=db.assets.find(a=>a.id===d.imageId);if(!a||a.approval!=='approved')return fail('Chọn ảnh đã duyệt trong tab Hình ảnh.');if(wfType==='pinterest'&&a.ratio!=='2:3')return fail('Ghim này cần ảnh dọc tỷ lệ 2:3.')}if(d.contentId&&wfType!=='asset'&&!db.content.some(c=>c.id===d.contentId))return fail('Nội dung gốc không còn tồn tại.');},true);
const priorTracking=trackingPage;trackingPage=function(){const metrics=periodMetrics(),sum=k=>metrics.reduce((n,m)=>n+Number(m[k]||0),0);return heading('Theo dõi','Hiệu quả sau đăng, liên kết trực tiếp về từng nội dung.',addBtn('metrics','Ghi số liệu'))+`<div class="filters"><select id="channelFilter" aria-label="Lọc kênh">${channelOptions()}</select><select id="period" aria-label="Khoảng thời gian">${opts([['month','Tháng này'],['last','Tháng trước'],['all','Tất cả thời gian']],period)}</select></div><div class="stats">${[['Lượt xem',sum('views')],['Tương tác',sum('likes')+sum('comments')+sum('shares')],['Nhấp link',sum('clicks')],['Theo dõi mới',sum('followers')]].map(([l,n])=>`<div class="stat"><span>${l}</span><strong>${num(n)}</strong></div>`).join('')}</div><section class="panel"><div class="panel-head"><h2>Hiệu quả từng nội dung</h2><span class="muted">Số liệu nhập tay, số tăng thêm</span></div><div class="table-wrap"><table><thead><tr><th>Nội dung</th><th>Cập nhật gần nhất</th><th class="num">Xem</th><th class="num">Thích / Bình luận / Chia sẻ</th><th class="num">Nhấp link</th><th></th></tr></thead><tbody>${[...db.content.filter(c=>!filterChannel||c.channelId===filterChannel).map(c=>({...c,metricId:c.id})),...db.workflows.filter(w=>!filterChannel||db.content.find(c=>c.id===w.contentId)?.channelId===filterChannel).map(w=>({...w,metricId:'wf:'+w.id}))].map(c=>{const ms=metrics.filter(m=>m.contentId===c.metricId),s=k=>ms.reduce((n,m)=>n+Number(m[k]||0),0);return `<tr><td>${esc(c.title)}</td><td>${ms.length?dateText(ms.map(m=>m.date).sort().at(-1)):'Chưa có số liệu'}</td><td class="num">${num(s('views'))}</td><td class="num">${num(s('likes'))} / ${num(s('comments'))} / ${num(s('shares'))}</td><td class="num">${num(s('clicks'))}</td><td><button data-record="${esc(c.metricId)}">Ghi số liệu</button></td></tr>`}).join('')}</tbody></table></div></section>`+priorTracking().slice(priorTracking().indexOf('<div class="grid two">'))};
const oldPromptsPage=promptsPage;promptsPage=function(){return heading('Câu lệnh','Điền biến, xem ngữ cảnh và kiểm tra trước khi chuyển sang AI.',addBtn('prompts','Thêm câu lệnh'))+`<div class="cards">${db.prompts.map(p=>`<article class="panel"><h2>${esc(p.name)}</h2><p>${esc(p.text.slice(0,220))}</p><div class="actions"><button class="primary" data-template="${p.id}">Điền biến và xem trước</button><button data-edit="prompts" data-id="${p.id}">Sửa mẫu</button></div></article>`).join('')}</div>`};
const picker=document.createElement('dialog');picker.innerHTML='<form id="pickerForm"><div class="dialog-head"><h2 id="pickerTitle"></h2><button type="button" id="pickerClose" aria-label="Đóng lựa chọn">×</button></div><div id="pickerFields" class="workflow-fields"></div><div class="dialog-actions"><button type="button" id="pickerCancel">Hủy</button><button class="primary" type="submit">Tiếp tục</button></div></form>';document.body.append(picker);let pickerResolve=null;
function choose(title,html){return new Promise(resolve=>{$('#pickerTitle').textContent=title;$('#pickerFields').innerHTML=html;pickerResolve=resolve;picker.showModal()})}
function closePick(){picker.close();pickerResolve?.(null);pickerResolve=null}$('#pickerClose').onclick=$('#pickerCancel').onclick=closePick;picker.oncancel=e=>{e.preventDefault();closePick()};$('#pickerForm').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData($('#pickerForm')));picker.close();pickerResolve?.(values);pickerResolve=null};
async function templatePreview(id){if(!db.channels.length)return toast('Thêm kênh trước khi dùng mẫu.');const p=db.prompts.find(p=>p.id===id),vars=[...new Set([...p.text.matchAll(/\{([^}]+)\}/g)].map(m=>m[1]))];let html=select('channelId','Kênh dùng mẫu',db.channels.map(c=>[c.id,c.name]),db.channels[0].id)+vars.map((v,i)=>input('v'+i,esc(v),'','text','required')).join('')+'<div class="field full"><label for="promptPreview">Xem trước câu lệnh hoàn chỉnh</label><textarea id="promptPreview" readonly></textarea></div>';const pending=choose('Điền biến và xem trước',html);const update=()=>{const d=Object.fromEntries(new FormData($('#pickerForm'))),c=ch(d.channelId);let t=p.text;vars.forEach((v,i)=>t=t.split('{'+v+'}').join(d['v'+i]||'{'+v+'}'));$('#promptPreview').value=t+'\n\nKênh: '+c?.name+'\nGiọng văn: '+(c?.style||'')+'\nĐối tượng: '+(c?.audience||'')};$('#pickerForm').oninput=update;update();const values=await pending;$('#pickerForm').oninput=null;if(values){let text=p.text;vars.forEach((v,i)=>text=text.split('{'+v+'}').join(values['v'+i]));openEditor('content','',{channelId:values.channelId,prompt:text,status:'idea'})}}
async function routeLineage(id,step){const c=db.content.find(c=>c.id===id);if(!c)return toast('Nội dung không còn tồn tại.');if($('#editor').open)closeEditor();if(step==='image'){location.hash='images';openWorkflow('asset','',{title:'Ảnh: '+c.title,contentId:c.id,globalStyle:ch(c.channelId)?.visual||'',scenePrompt:c.imagePrompt||c.title,ratio:'2:3'});return}if(step==='variant'){const d=await choose('Tạo phiên bản từ nội dung gốc',select('channelId','Kênh đích',db.channels.map(c=>[c.id,c.name]),c.channelId)+select('kind','Định dạng',['Teaser','Video ngắn','Bài viết'], 'Teaser'));if(d)openEditor('content','',{title:c.title+' — '+d.kind,channelId:d.channelId,parentId:c.id,kind:d.kind,status:'draft',prompt:'Chuyển thể nội dung gốc dưới đây thành '+d.kind+' theo giọng văn kênh đích. Không bịa thêm sự kiện.\n\n'+c.body});return}const a=db.assets.find(a=>a.contentId===c.id&&a.approval==='approved'&&a.data);location.hash=step;openWorkflow(step,'',{title:c.title,contentId:c.id,description:c.body,imageId:a?.id||'',status:'draft'})}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.pubtab){publicationMode=b.dataset.pubtab;render()}if(b.dataset.imagetab){imageMode=b.dataset.imagetab;render()}if(b.dataset.lineage)await routeLineage(b.dataset.lineage,b.dataset.step);if(b.dataset.template)await templatePreview(b.dataset.template);if(b.hasAttribute('data-editor-close')&&$('#editor').open)closeEditor();if(b.dataset.record){const id=b.dataset.record,c=id.startsWith('wf:')?db.workflows.find(w=>w.id===id.slice(3)):db.content.find(c=>c.id===id);const channel=id.startsWith('wf:')?db.content.find(c=>c.id===db.workflows.find(w=>w.id===id.slice(3))?.contentId)?.channelId:c?.channelId;if(!channel)return toast('Liên kết gói nền tảng với nội dung thuộc kênh trước khi ghi số liệu.');openEditor('metrics','',{channelId:channel,contentId:id,date:today(),source:id.startsWith('wf:')?(c.type==='etsy'?'Etsy':'Pinterest / Affiliate'):defaultSource(ch(channel)?.platform)})}if(b.dataset.restoreHistory){const c=db.content.find(c=>c.id===b.dataset.restoreHistory),h=c?.history?.[Number(b.dataset.hi)];if(h){$('#fields [name="title"]').value=h.title;$('#fields [name="body"]').value=h.body;toast('Đã đưa phiên bản cũ vào trình soạn. Bấm Lưu để áp dụng.')}}if(b.id==='composeLayers'){const d=wfValues();$('#workflowFields [name="prompt"]').value=['Create exactly one standalone image.','Aspect ratio: '+d.ratio,'GLOBAL STYLE: '+d.globalStyle,'SCENE: '+d.scenePrompt,'No collage, no watermark. Accurately follow the supplied content; do not invent unsupported events.'].join('\n\n')}if(b.dataset.original)await downloadOriginal(b.dataset.original)});
document.addEventListener('change',e=>{if(e.target.name==='contentId'&&wfDialog.open&&wfType!=='asset'){const c=db.content.find(c=>c.id===e.target.value);if(c){const description=$('#workflowFields [name="description"]');if(!description.value)description.value=c.body||'';const a=db.assets.find(a=>a.contentId===c.id&&a.approval==='approved'&&a.data);if(a)$('#workflowFields [name="imageId"]').value=a.id}}if(e.target.name==='channelId'&&$('#editor').open&&editType==='metrics'){const el=$('#fields [name="contentId"]');if(el)el.innerHTML=opts([['','Số liệu chung của kênh'],...db.content.filter(c=>c.channelId===e.target.value).map(c=>[c.id,c.title]),...db.workflows.filter(w=>db.content.find(c=>c.id===w.contentId)?.channelId===e.target.value).map(w=>['wf:'+w.id,w.title])],'')}});
// Preserve original image bytes separately from lightweight previews.
function originalStore(){return new Promise((resolve,reject)=>{const request=indexedDB.open('xuong-original-images',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function putOriginal(key,file){const database=await originalStore();try{await new Promise((resolve,reject)=>{const tx=database.transaction('files','readwrite');tx.objectStore('files').put(file,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}finally{database.close()}}
async function readOriginal(key){const database=await originalStore();try{return await new Promise((resolve,reject)=>{const r=database.transaction('files').objectStore('files').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}finally{database.close()}}
async function downloadOriginal(id){const a=db.assets.find(a=>a.id===id);let blob;try{blob=a?.originalKey?await readOriginal(a.originalKey):null}catch{}const link=document.createElement('a');if(blob){const url=URL.createObjectURL(blob);link.href=url;link.download=blob.name||'anh-goc';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}else if(a?.data){link.href=a.data;link.download='anh-preview-'+id+'.jpg';link.click();toast('Không có bản gốc trên thiết bị này; đã tải ảnh xem trước.')}else toast('Chưa có ảnh kết quả.')}
document.addEventListener('change',async e=>{if(e.target.id!=='assetFile')return;const file=e.target.files[0];if(!file||file.size>10*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type))return;const key=uid(),button=$('#workflowForm button[type="submit"]');button.disabled=true;try{await putOriginal(key,file);$('#workflowFields [name="originalKey"]').value=key}catch{workflowError('Không lưu được bản gốc. Ảnh xem trước vẫn có thể lưu; hãy giữ file gốc trên máy.')}finally{button.disabled=false}},true);
const priorSettings=settingsPage;settingsPage=function(){return priorSettings()+`<section class="panel mt"><h2>File ảnh gốc</h2><p class="help-text mt">Ảnh gốc giữ trong bộ nhớ IndexedDB của thiết bị này. Sao lưu JSON gồm ảnh xem trước và các liên kết, không chứa file ảnh gốc. Tải file gốc riêng trước khi đổi trình duyệt hoặc xóa dữ liệu.</p></section>`};
render();
